export const ASSISTED_LABELS={review:'Revisão Helpu',awaiting_approval:'Aguardando sua aprovação',scheduled:'Aprovado · aguarda publicação',publishing:'Publicação manual em andamento',published:'Publicado · registro da equipe',changes_requested:'Ajustes solicitados',failed:'Precisa de correção',uncertain:'Resultado a conferir',canceled:'Cancelado',requested:'Verba solicitada',quoted:'Orçamento para aprovar',approved:'Orçamento aprovado',configured:'Anúncio configurado',meta_review:'Em análise na Meta',active:'Anúncio ativo',closed:'Anúncio encerrado',results:'Resultados registrados'};
export function createAssistedUI({api,esc,getState,getBoot,openDialog,closeDialog,toast}){
  let active=false,admin=false,data=null,company='',ticket=0,filter='all',clientFilter='all',pending=false;
  const label=s=>ASSISTED_LABELS[s]||s;
  const money=v=>v===null||v===undefined?'A definir':new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v/100);
  const date=(v,tz)=>v?new Date(v).toLocaleString('pt-BR',tz?{timeZone:tz}:undefined):'—';
  const local=v=>{if(!v)return '';const d=new Date(v);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);};
  const button=(name,action,id='',style='secondary')=>`<button class="p-button ${style}" type="button" data-assisted="${action}" data-id="${esc(id)}">${esc(name)}</button>`;
  const field=(name,title,value='',type='text',required=true)=>`<label class="p-field"><span>${esc(title)}</span><input name="${name}" type="${type}" ${type==='number'?'step="0.01" min="0"':''} value="${esc(value)}" ${required?'required':''}></label>`;
  const area=(name,title,value='')=>`<label class="p-field"><span>${esc(title)}</span><textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;
  const check=(name,title)=>`<label class="assisted-check"><input type="checkbox" name="${name}" required><span>${esc(title)}</span></label>`;
  const error='<p class="form-error" role="alert" hidden></p>';
  const requests=()=>data?.requests||[];
  const serviceFor=org=>admin?data.clients?.find(c=>c.id===org)?.service:data?.service;
  const companyName=org=>admin?data.clients?.find(c=>c.id===org)?.name:getState()?.company.name;
  const endpoint=()=>admin?'/api/portal/assisted-admin':'/api/portal/'+company+'/assisted';
  const mayManage=()=>admin||data?.canManage;
  function card(r){const s=r.snapshot;return `<article class="panel assisted-card"><div class="assisted-card-head"><div><p class="overline">${esc(companyName(r.orgId))} · VERSÃO ${r.revision}</p><h2>${esc(s.title)}</h2></div><span class="p-tag">${esc(label(r.state))}</span></div><p>@${esc(s.account)} · ${esc(s.format)} · ${esc(date(s.scheduledAt,s.timeZone))} (${esc(s.timeZone)})</p>${Date.parse(s.scheduledAt)<Date.now()&&!['published','canceled'].includes(r.state)?'<p class="assisted-warning">O horário previsto passou. Confira o andamento com a equipe.</p>':''}<p>${r.assignee?'Responsável: '+esc(data?.operators?.find(o=>o.id===r.assignee)?.name||'Equipe Helpu'):'Aguardando responsável'}${r.boost?' · '+esc(label(r.boost.state))+' · mídia '+money(r.boost.terms.budgetCents):''}</p>${serviceFor(r.orgId)?.active&&serviceFor(r.orgId)?.authorizationId!==r.authorizationId?'<p class="assisted-warning">A autorização mudou. Envie uma nova versão para revisão.</p>':''}${!serviceFor(r.orgId)?.active?'<p class="assisted-warning">Autorização do serviço desativada.</p>':''}${button('Abrir pedido','detail',r.id)}</article>`;}
  function paint(){const host=document.querySelector('#assisted-workspace');if(!active||!host)return;
    if(!data){host.innerHTML='<p>Carregando pedidos…</p>';return;}
    const service=data.service;
    const authorization=admin?'':`<section class="panel assisted-card"><h2>Autorização do serviço</h2><p>A equipe revisa e publica manualmente. O pedido não é uma garantia de atendimento imediato: aguarde a revisão e confirme a data com a Helpu.</p><p>Conceda acesso delegado na Meta. Não informe a senha do Instagram aqui ou no chat. Autorizar o serviço não concede esse acesso técnico.</p>${service?.active?`<p><strong>Autorizado para @${esc(service.account)}</strong> · ${service.delegated?'Acesso delegado conferido pela equipe':'Aguardando conferência do acesso delegado'}</p>${data.canManage?button('Revogar autorização','revoke'):''}<p class="micro-copy">Revogar bloqueia novos inícios. Uma publicação já iniciada pode estar em andamento na Meta; fale com a equipe.</p>`:data.canManage?`<form data-assisted-form="authorize" data-version="${service?.version||0}">${field('account','Usuário do Instagram',service?.account||'')}${check('consent',data.consentText)}${error}<button class="p-button primary">Autorizar serviço</button></form>`:'<p>Peça ao responsável pela empresa para autorizar.</p>'}</section>`;
    const clients=admin?`<details class="panel assisted-card"><summary>Clientes e acessos delegados (${data.clients.length})</summary>${data.clients.map(c=>`<article class="assisted-client"><h3>${esc(c.name)}</h3><p>@${esc(c.service?.account||'')} · ${c.service?.active?'Serviço autorizado':'Autorização revogada'} · ${c.service?.delegated?'Acesso conferido':'Acesso pendente'}</p>${Object.entries({description:'Empresa',audience:'Público',tone:'Tom de voz',visualIdentity:'Identidade visual',restrictions:'Restrições'}).filter(([key])=>c.profile?.[key]).map(([key,title])=>`<p><strong>${title}:</strong> ${esc(c.profile[key])}</p>`).join('')}${c.service?.active?button('Conferir acesso delegado','verify',c.id):''}</article>`).join('')||'<p>Ainda não há clientes com este serviço.</p>'}</details>`:'';
    const items=requests().filter(r=>(filter==='all'||r.state===filter)&&(clientFilter==='all'||r.orgId===clientFilter)).sort((a,b)=>Date.parse(a.snapshot.scheduledAt)-Date.parse(b.snapshot.scheduledAt));
    host.innerHTML=authorization+clients+`<div class="assisted-toolbar">${admin?`<label class="p-field"><span>Cliente</span><select id="assisted-client-filter"><option value="all">Todos os clientes</option>${data.clients.map(c=>`<option value="${esc(c.id)}" ${clientFilter===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label>`:''}<label class="p-field"><span>Filtrar pedidos</span><select id="assisted-filter"><option value="all">Todos</option>${['review','awaiting_approval','scheduled','publishing','changes_requested','failed','uncertain','published','canceled'].map(s=>`<option value="${s}" ${filter===s?'selected':''}>${esc(label(s))}</option>`).join('')}</select></label>${!admin&&data.canManage&&service?.active?button('Solicitar publicação','new','','primary'):''}${button('Atualizar fila','refresh')}</div><div class="assisted-list">${items.map(card).join('')||'<section class="panel assisted-card"><h2>Nenhum pedido nesta fila</h2><p>Os pedidos de publicação e seus próximos passos aparecerão aqui.</p></section>'}</div>`;
  }
  async function load(){const seq=++ticket,org=company,mode=admin;try{const result=await api(endpoint());if(seq===ticket&&active&&org===company&&mode===admin){data=result;paint();}}catch(e){if(seq===ticket&&active){const host=document.querySelector('#assisted-workspace');if(host)host.innerHTML=`<p role="alert">${esc(e.message)}</p>${button('Tentar novamente','refresh')}`;}}}
  function summary(r){const s=r.snapshot;return `<p class="overline">${esc(companyName(r.orgId))} · VERSÃO ${r.revision} · ${esc(label(r.state))}</p><h3>${esc(s.title)}</h3><dl class="assisted-facts"><dt>Conta</dt><dd>@${esc(s.account)}</dd><dt>Formato</dt><dd>${esc(s.format)}</dd><dt>Data aprovada/proposta</dt><dd>${esc(date(s.scheduledAt,s.timeZone))} (${esc(s.timeZone)})</dd></dl><div class="assisted-media">${s.assets.map(a=>`<figure>${a.mime.startsWith('video/')?`<video controls preload="metadata" src="/api/portal/files/${encodeURIComponent(a.id)}"></video>`:`<img src="/api/portal/files/${encodeURIComponent(a.id)}" alt="${esc(a.name)}">`}<figcaption><a href="/api/portal/files/${encodeURIComponent(a.id)}" target="_blank" rel="noopener">${esc(a.name)} ↗</a></figcaption></figure>`).join('')}</div><h3>Legenda desta versão</h3><p class="assisted-caption">${esc(s.caption||'Sem legenda')}</p>${r.note?`<p class="assisted-warning">${esc(r.note)}</p>`:''}${r.publication?`<p><a href="${esc(r.publication.url)}" target="_blank" rel="noopener">Ver publicação registrada ↗</a> · ${esc(date(r.publication.at))}</p><p class="micro-copy">Resultado informado pelo operador ${esc(r.publication.operator)}; não é confirmação automática da Meta.</p>`:''}`;}
  function approval(r,boost=false){return `<form data-assisted-form="${boost?'boost_approve':'approve'}" data-id="${esc(r.id)}" data-version="${r.version}">${check('consent',boost?'Aprovo esta verba de mídia, a taxa Helpu, o público e o período apresentados.':'Conferi os arquivos, a conta, a legenda e a data desta versão e autorizo a publicação manual.')}${error}<button class="p-button primary">${boost?'Aprovar orçamento':'Aprovar esta versão'}</button></form>`;}
  function detail(r){const s=serviceFor(r.orgId),editable=!['publishing','published','uncertain','canceled'].includes(r.state),b=r.boost;
    const boost=b?`<section class="assisted-boost"><h3>Impulsionamento · ${esc(label(b.state))}</h3><p>Mídia: <strong>${money(b.terms.budgetCents)}</strong> · Taxa Helpu: <strong>${money(b.terms.feeCents)}</strong></p><p>Total: ${b.terms.feeCents===null?'aguarda orçamento':money(b.terms.budgetCents+b.terms.feeCents)}. A mídia é paga pelo cliente diretamente à Meta. Nenhum pagamento é iniciado aqui.</p><p>${esc(b.terms.objective)} · ${esc(b.terms.audience)}</p><p>${esc(date(b.terms.startAt))} até ${esc(date(b.terms.endAt))} (horário deste dispositivo)</p>${!admin&&data.canManage&&b.state==='quoted'?approval(r,true):''}${admin&&['requested','quoted','approved'].includes(b.state)?button('Validar / rever orçamento','quote',r.id):''}${admin&&['approved','configured','meta_review','active','closed'].includes(b.state)?button('Registrar próxima etapa do anúncio','boost_status',r.id):''}${b.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(label(e.state))}</a>: ${esc(e.note)}</p>`).join('')}</section>`:'';
    let actions='';if(mayManage()){
      if(editable)actions+=button('Editar e criar nova versão','revise',r.id)+button('Solicitar ajuste','changes',r.id);
      if(!['publishing','published','uncertain','canceled'].includes(r.state))actions+=button('Cancelar pedido','cancel',r.id);
      if(admin&&s?.active){actions+=button('Assumir atendimento','assign',r.id);if(['review','changes_requested','failed'].includes(r.state))actions+=button('Enviar versão para aprovação','submit_review',r.id);if(r.state==='scheduled')actions+=button('Iniciar publicação manual','start_publication',r.id);}
      if(admin&&['publishing','uncertain'].includes(r.state))actions+=button('Registrar link publicado','published',r.id);
      if(admin&&['review','awaiting_approval','scheduled','publishing'].includes(r.state))actions+=button('Registrar impedimento','failed',r.id);
    }
    openDialog('Pedido de publicação',`<div class="assisted-detail">${summary(r)}${!admin&&data.canManage&&r.state==='awaiting_approval'?approval(r):''}${boost}<div class="assisted-actions">${actions}</div><details><summary>Histórico e versões anteriores</summary>${r.history.map(e=>`<p>${esc(date(e.at))} · ${esc(e.role==='operator'?'Equipe':'Cliente')} ${esc(e.actor)} · ${esc(actionName(e.action))}${e.revision?' · versão '+e.revision:''}${e.budget?' · mídia '+money(e.budget.terms.budgetCents)+' · taxa '+money(e.budget.terms.feeCents):''}</p>`).join('')}${r.revisions.map(v=>`<details><summary>Versão ${v.revision}</summary><p>@${esc(v.snapshot.account)} · ${esc(date(v.snapshot.scheduledAt,v.snapshot.timeZone))}</p><p class="assisted-caption">${esc(v.snapshot.caption)}</p><p>${v.snapshot.assets.map(a=>esc(a.name)).join(', ')}</p></details>`).join('')}</details></div>`,true);
  }
  function actionName(a){return {create:'Pedido criado',authorize:'Serviço autorizado',revoke:'Autorização revogada',verify_access:'Acesso delegado conferido',revise:'Nova versão criada',approve:'Versão aprovada',changes:'Ajustes solicitados',cancel:'Pedido cancelado',assign:'Responsável atribuído',submit_review:'Enviado para aprovação',start_publication:'Publicação manual iniciada',published:'Publicação registrada',failed:'Impedimento registrado',quote:'Orçamento revisado',boost_approve:'Orçamento aprovado',boost_status:'Etapa do anúncio registrada'}[a]||a;}
  function requestForm(r){const s=r?.snapshot||{},b=r?.boost?.terms||{},assets=admin?(r?.snapshot.assets||[]):getState().assets.filter(a=>/^(image\/(jpeg|png|webp)|video\/mp4)$/.test(a.mime));
    openDialog(r?'Nova versão do pedido':'Solicitar publicação',`<form data-assisted-form="${r?'revise':'create'}" data-id="${esc(r?.id||'')}" data-version="${r?.version||0}" data-request-key="${crypto.randomUUID()}">${field('title','Título do pedido',s.title||'')}<label class="p-field"><span>Formato</span><select name="format">${[['feed','Feed'],['story','Story'],['reels','Reels'],['carousel','Carrossel']].map(([id,name])=>`<option value="${id}" ${s.format===id?'selected':''}>${name}</option>`).join('')}</select></label><fieldset class="assisted-assets"><legend>Arquivos finais, na ordem de publicação</legend>${assets.map(a=>`<label class="assisted-check"><input type="checkbox" name="assetIds" value="${esc(a.id)}" ${s.assets?.some(x=>x.id===a.id)?'checked':''}><span>${esc(a.name)}</span></label>`).join('')||'<p>Adicione o arquivo pronto pela Conversa ou crie o material antes de solicitar.</p>'}</fieldset>${area('caption','Legenda final',s.caption||'')}${field('scheduledAt','Data e horário desejados (horário deste dispositivo)',local(s.scheduledAt),'datetime-local')}<p class="micro-copy">A equipe precisa revisar e você precisa aprovar antes da publicação. Esta solicitação não publica automaticamente.</p><details ${r?.boost?'open':''}><summary>Solicitar impulsionamento (opcional)</summary><label class="assisted-check"><input name="boostRequested" type="checkbox" ${r?.boost?'checked':''}><span>Quero receber orçamento para impulsionar esta peça.</span></label><label class="p-field"><span>Intenção de verba de mídia</span><select name="budgetCents">${[3500,5000,10000].map(v=>`<option value="${v}" ${b.budgetCents===v?'selected':''}>${money(v)}</option>`).join('')}</select></label>${field('objective','Objetivo do anúncio',b.objective||'','text',false)}${field('audience','Cidade e público',b.audience||'','text',false)}${field('startAt','Início desejado',local(b.startAt),'datetime-local',false)}${field('endAt','Fim desejado',local(b.endAt),'datetime-local',false)}<p>A verba depende de validação. Taxa Helpu, se houver, será apresentada separadamente antes de aprovar. Não há promessa de alcance ou vendas.</p></details>${error}<button class="p-button primary">${r?'Salvar nova versão para revisão':'Enviar pedido para revisão'}</button></form>`,true);
  }
  function actionDialog(act,r){
    const service=serviceFor(r?.orgId||r?.id||company),orgId=r?.orgId||r?.id||company;
    let fields='',title=actionName(act),version=r?.version||service?.version||0;
    if(act==='verify'){title='Conferir acesso delegado';fields='<p>Confira na Meta o acesso da equipe à conta @'+esc(service.account)+'. Esta confirmação é um registro humano, não uma validação automática.</p>'+area('evidence','Como o acesso foi conferido');version=service.version;}
    else if(act==='quote'){const b=r.boost.terms;title='Validar orçamento';fields=field('budget','Verba total de mídia (R$)',b.budgetCents/100,'number')+field('fee','Taxa Helpu separada (R$)',b.feeCents===null?'':b.feeCents/100,'number')+field('startAt','Início (horário deste dispositivo)',local(b.startAt),'datetime-local')+field('endAt','Fim (horário deste dispositivo)',local(b.endAt),'datetime-local')+area('note','Observações');}
    else if(act==='boost_status'){const state={approved:'configured',configured:'meta_review',meta_review:'active',active:'closed',closed:'results'}[r.boost.state];title='Registrar: '+label(state);fields=`<input type="hidden" name="state" value="${state}">`+field('url','Link da campanha no Gerenciador de Anúncios','','url')+area('evidence','Evidência ou resultados observados');}
    else if(act==='published')fields=field('url','Link da publicação no Instagram','','url')+area('note','Observações da publicação');
    else if(act==='changes'||act==='failed'||act==='submit_review')fields=area('note',act==='submit_review'?'Observações para revisão':'Explique o que precisa de atenção');
    else if(act==='start_publication')fields='<p>Esta etapa reserva a execução para você. Publique manualmente somente os arquivos e a legenda aprovados, na conta indicada. Depois, registre o link. Se não souber se publicou, registre o impedimento e confira a conta antes de repetir.</p>';
    else if(act==='revoke')fields='<p>Novos inícios serão bloqueados. Uma ação já iniciada na Meta pode continuar; confira com a equipe.</p>';
    else fields='<p>Confirme esta ação no pedido selecionado.</p>';
    openDialog(title,`<form data-assisted-form="${act==='verify'?'verify_access':act}" data-id="${esc(r?.id||'')}" data-org="${esc(orgId)}" data-version="${version}">${fields}${error}<button class="p-button primary">Confirmar</button></form>`);
  }
  document.addEventListener('click',event=>{const b=event.target.closest('[data-assisted]');if(!b||!active||pending)return;const act=b.dataset.assisted,r=requests().find(r=>r.id===b.dataset.id);if(act==='refresh'){load();return;}if(act==='new'){requestForm();return;}if(act==='detail'&&r){detail(r);return;}if(act==='revise'&&r){requestForm(r);return;}if(act==='verify'){actionDialog(act,{id:b.dataset.id});return;}if(act==='revoke'){actionDialog(act);return;}if(r)actionDialog(act,r);});
  document.addEventListener('change',event=>{if(event.target.id==='assisted-client-filter'){clientFilter=event.target.value;paint();}if(event.target.id==='assisted-filter'){filter=event.target.value;paint();}});
  document.addEventListener('submit',async event=>{
    const f=event.target.closest('[data-assisted-form]');if(!f||!active)return;event.preventDefault();if(pending)return;const action=f.dataset.assistedForm,r=requests().find(r=>r.id===f.dataset.id),form=new FormData(f),input={...Object.fromEntries(form),action,id:f.dataset.id,orgId:r?.orgId||f.dataset.org||company,version:Number(f.dataset.version),consent:form.get('consent')==='on'};
    const mode=admin,org=company,url=endpoint();
    try{
      if(['create','revise'].includes(action)){input.requestKey=f.dataset.requestKey;input.assetIds=form.getAll('assetIds');input.scheduledAt=new Date(input.scheduledAt).toISOString();input.timeZone=Intl.DateTimeFormat().resolvedOptions().timeZone;input.boost=form.get('boostRequested')==='on'?{requested:true,budgetCents:Number(input.budgetCents),objective:input.objective,audience:input.audience,startAt:new Date(input.startAt).toISOString(),endAt:new Date(input.endAt).toISOString()}:null;}
      if(action==='quote'){input.budgetCents=Math.round(Number(input.budget)*100);input.feeCents=Math.round(Number(input.fee)*100);input.startAt=new Date(input.startAt).toISOString();input.endAt=new Date(input.endAt).toISOString();}
      pending=true;f.querySelector('button[type="submit"],button:not([type])').disabled=true;
      await api(url,'POST',input);
      if(active&&admin===mode&&company===org){closeDialog();toast('Alteração registrada.');await load();}
    }catch(e){const error=f.querySelector('[role="alert"]');error.textContent=e.message;error.hidden=false;}
    finally{pending=false;const button=f.querySelector('button[type="submit"],button:not([type])');if(button)button.disabled=false;}
  });
  return {page(mode=false){return `<section class="page-heading"><div><p class="overline">${mode?'OPERAÇÃO HELPU':'PUBLICAÇÃO ASSISTIDA'}</p><h1>${mode?'Fila da equipe':'Seu conteúdo, acompanhado.'}</h1><p>${mode?'Revise, obtenha aprovação e registre a execução manual.':'Peça a revisão e acompanhe a publicação pela equipe Helpu.'}</p></div></section><div id="assisted-workspace"></div>`;},mount(view){const next=view==='assisted'||view==='admin';if(!next){active=false;++ticket;return;}if(admin!==(view==='admin'))clientFilter='all';admin=view==='admin';active=true;company=getState()?.company.id||'';data=null;if(admin&&!getBoot()?.operator){document.querySelector('#assisted-workspace').innerHTML='<p>Acesso restrito à equipe autorizada.</p>';return;}paint();load();}};
}
